PREFIX = {'Improved': {'m':'Perfezionato','f':'Perfezionata','mp':'Perfezionati','fp':'Perfezionate'},
          'Advanced': {'m':'Superiore','f':'Superiore','mp':'Superiori','fp':'Superiori'},
          'Legendary':{'m':'Leggendario','f':'Leggendaria','mp':'Leggendari','fp':'Leggendarie'}}

def name_it(en):
    m = re.match(r'^(Improved|Advanced|Legendary)\s+(.*)$', en)
    if m:
        base, g = N[m[2]]
        return f"{base} {PREFIX[m[1]][g]}"
    return N[en][0]

