def feature_it(en):
    if not en: return ''
    parts = re.split(r';\s*(?=[A-Z][a-z]+(?:[ -][A-Z][a-z]+)?:)', en)
    out = []
    for part in parts:
        m = re.match(r"([A-Z][\w’' -]+?):\s*(.*)", part)
        if not m or m[1] not in F:
            raise KeyError(part)
        name, tx = F[m[1]]
        text = tx(m[2].strip()) if callable(tx) else tx
        out.append(f"{name}: {text}")
    return '; '.join(out)
